settings.custom_liquid:
{% if request.locale.iso_code == 'en' %}
<div class="feature-wrapper" style="
  display: flex;
  justify-content: {{ alignment | default: 'center' }};
  width: 100%;
  margin-top: {{ margin_top | default: '20px' }};
  margin-bottom: {{ margin_bottom | default: '20px' }};
">
  <div class="feature-container">

    <div class="feature-item">
      <img src="https://cdn.shopify.com/s/files/1/0758/2600/4221/files/check_2.png?v=1765915937" alt="Check Icon" class="feature-icon blue-check">
      <div class="feature-text">Warms Milk in Minutes, So Your Baby Doesn’t Have to Wait</div>
    </div>

    <div class="feature-item">
      <img src="https://cdn.shopify.com/s/files/1/0758/2600/4221/files/check_2.png?v=1765915937" alt="Check Icon" class="feature-icon blue-check">
      <div class="feature-text">One Device for Everything: Warm Milk, Defrost, Sterilize & Heat Food</div>
    </div>

    <div class="feature-item">
      <img src="https://cdn.shopify.com/s/files/1/0758/2600/4221/files/check_2.png?v=1765915937" alt="Check Icon" class="feature-icon blue-check">
      <div class="feature-text">Heats to the Perfect Temperature Without Destroying Nutrients</div>
    </div>

    <div class="feature-item">
      <img src="https://cdn.shopify.com/s/files/1/0758/2600/4221/files/check_2.png?v=1765915937" alt="Check Icon" class="feature-icon blue-check">
      <div class="feature-text">Keeps Milk Warm and Ready for Night Feeds</div>
    </div>

    <div class="feature-item">
      <img src="https://cdn.shopify.com/s/files/1/0758/2600/4221/files/check_2.png?v=1765915937" alt="Check Icon" class="feature-icon blue-check">
      <div class="feature-text">Built-In Safety Protection Prevents Overheating or Dry Heating</div>
    </div>

    <div class="feature-item">
      <img src="https://cdn.shopify.com/s/files/1/0758/2600/4221/files/check_2.png?v=1765915937" alt="Check Icon" class="feature-icon blue-check">
      <div class="feature-text">Easy Touch Screen with Soft Night Light for Late-Night Use</div>
    </div>

  </div>
</div>

{% style %}
  :root {
    --text-color: {{ text_color | default: "#333" }};
    --hover-bg-color: {{ hover_bg_color | default: "#f4fbff" }};
    --highlight-color: {{ highlight_color | default: "#000" }};
    --transition-duration: {{ transition_duration | default: "0.25s" }};
    --font-family: {{ font_family | default: "'Helvetica Neue', Arial, sans-serif" }};
    --icon-size: {{ icon_size | default: "18px" }};
    --font-size: {{ font_size | default: "15px" }};
    --font-size-mobile: {{ font_size_mobile | default: "14px" }};
  }

  .feature-wrapper {
    width: 100%;
  }

  @media (max-width: 768px) {
    .feature-wrapper {
      justify-content: {{ mobile_alignment | default: "center" }} !important;
    }
  }

  .feature-container {
    max-width: 600px;
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 6px;
    font-family: var(--font-family);
  }

  .feature-item {
    display: flex;
    align-items: center;
    padding: 6px 0;
    border-radius: 8px;
    transition: background-color var(--transition-duration), transform var(--transition-duration);
    cursor: default;
  }

  .feature-item:hover {
    background-color: var(--hover-bg-color);
    transform: translateX(8px);
  }

  .feature-icon {
    width: var(--icon-size);
    height: var(--icon-size);
    margin-right: 10px;
  }

  .blue-check {
    filter: brightness(0) saturate(100%) invert(74%) sepia(25%) saturate(544%) hue-rotate(162deg) brightness(96%) contrast(92%);
  }

  .feature-text {
    font-size: var(--font-size);
    color: var(--text-color);
  }

  .feature-item:hover .feature-text {
    color: var(--highlight-color);
  }

  @media (max-width: 600px) {
    .feature-text {
      font-size: var(--font-size-mobile);
    }
  }
{% endstyle %}
{% endif %}

