{% if request.locale.iso_code == 'en' %}
<form method="post" action="/cart/add" class="buy-now-form" style="margin-top: 12px;">
  <input type="hidden" name="id" value="{{ product.selected_or_first_available_variant.id }}">
  <input type="hidden" name="quantity" value="1">
  <button type="submit" name="checkout" value="true" class="button button--primary" style="width: 100%; background-color: #FF8C42; color: #FFFFFF;">
    Buy Now
  </button>
</form>
<script>
  document.querySelector('.buy-now-form').addEventListener('submit', function(e) {
    e.preventDefault();
    const formData = new FormData(this);
    fetch('/cart/add.js', {
      method: 'POST',
      body: formData
    })
    .then(response => response.json())
    .then(data => {
      window.location.href = '/checkout';
    })
    .catch(error => console.error('Error:', error));
  });
</script>
{% endif %}

